/*
 * A139497  Primes of the form x^2 + 15x*y + y^2 for x and y nonnegative.
 * https://oeis.org/A139497
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth prime of the form x² + 15 x y + y² with
 *            non‑negative integers x, y, listed in increasing order. The
 *            sequence is generated by enumerating the values in sorted order
 *            using a min‑heap, testing each for primality, and discarding
 *            duplicates
 * Range:     u8 n <= 4, u16 n <= 46, u32 n <= 46, u64 n <= 46, u128 n <= 46,
 *            big any n
 * Helpers:   is_prime_big, make_val
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* ----  Required includes for C11 and C++17  ---- */
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/is_prime_big.h"   /* bool is_prime_big(seq_t n) */
#include "../utils/make_val.h"

/* ----  heap node  ---- */
typedef struct {
    seq_t  val;
    uint32_t x;
    uint32_t y;
} heap_node;

/* ----  global state for the heap and cache  ---- */
static heap_node *heap          = NULL;   /* 1‑based heap array    */
static size_t    heap_size      = 0;     /* current number of elements   */
static size_t    heap_cap       = 0;     /* current capacity of heap     */
static uint32_t  next_new_x     = 1;     /* next x not yet inserted      */

static seq_t *cache            = NULL;   /* list of found primes        */
static size_t  cache_len       = 0;
static size_t  cache_cap       = 0;
static seq_t   last_val        = 0;      /* last cached prime           */

/* ----  heap utilities  ---- */
static void heap_grow(void)
{
    size_t new_cap = heap_cap ? heap_cap * 2 : 8;
    heap_node *tmp  = (heap_node *)realloc(heap, new_cap * sizeof(heap_node));
    heap    = tmp;
    heap_cap= new_cap;
}

static void heap_push(uint32_t x, uint32_t y, seq_t v)
{
    if (heap_cap == 0 || heap_size == heap_cap) heap_grow();
    size_t i = heap_size++;
    heap[i].val = v;
    heap[i].x   = x;
    heap[i].y   = y;
    /* bubble up */
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p].val <= heap[i].val) break;
        heap_node t = heap[i]; heap[i] = heap[p]; heap[p] = t;
        i = p;
    }
}

static heap_node heap_pop(void)
{
    heap_node top = heap[0];
    heap[0] = heap[--heap_size];
    /* bubble down */
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        if (l >= heap_size) break;
        size_t r = l + 1;
        size_t j = (r < heap_size && heap[r].val < heap[l].val) ? r : l;
        if (heap[i].val <= heap[j].val) break;
        heap_node t = heap[i]; heap[i] = heap[j]; heap[j] = t;
        i = j;
    }
    return top;
}

/* ----  cache utilities  ---- */
static void cache_append(seq_t v)
{
    if (cache_cap == 0 || cache_len == cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 8;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        cache = tmp;
        cache_cap = new_cap;
    }
    cache[cache_len++] = v;
}

/* ----  main sequence function  ---- */
seq_t a(idx_t n)
{
    if (n < (idx_t)1) return 0;

    /* generate terms until we have n of them */
    while (cache_len < n) {
        /* ensure the first element (x = 0, y = 1) is present */
        if (heap_size == 0) {
            heap_push(0, 1, make_val(0, 1));
        }

        /* insert new xs whose minimal value is <= current minimum */
        while (1) {
            seq_t newv = make_val(next_new_x, 1);
            if (heap_size == 0 || newv <= heap[0].val) {
                heap_push(next_new_x, 1, newv);
                ++next_new_x;
            } else break;
        }

        /* take the smallest candidate */
        heap_node cur = heap_pop();

        /* enqueue the next y for the same x */
        heap_push(cur.x, cur.y + 1, make_val(cur.x, cur.y + 1));

        /* cache if prime and not a duplicate */
        if (cur.val >= (seq_t)2 && cur.val != last_val && is_prime_big(cur.val)) {
            cache_append(cur.val);
            last_val = cur.val;
        }
    }

    return cache[n - 1];
}
